foundation.question_text:
A curve has parametric equations $x=t^{2}$ and $y=2t$.
Find the equation of the tangent to the curve at the point where $t=4$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-3, xmax=23.5, ymin=-10.5, ymax=10.5, xtick={4,8,12,16,20}, ytick={-8,-4,4,8}, samples=120, clip=false, width=10cm, height=8.5cm]
\addplot[thick, <->, variable=\t, domain=-4.6:4.6] ({\t*\t},{2*\t}) node[pos=0.04, below left] {$x=t^{2},\ y=2t$};
\addplot[dashed, <->, domain=-3:23.5] {x/4 + 4} node[pos=0.35, above left] {tangent at $t=4$};
\addplot[only marks, mark=*] coordinates {(16,8)};
\node[below right] at (axis cs:16,8) {$P$};
\end{axis}
\end{tikzpicture}
[/tikz]
